=== FILE: tb/irq_ctrl_tb.sv ===
// Self-checking testbench for irq_ctrl (task prj-486b52a6aa:testbench).
// Expected values come from interface_spec.md: a reference model written from
// the specification text plus literal expectations in the directed scenarios.
// Nothing is copied from the DUT's outputs.
//
// Timing: inputs are driven at the falling edge of clk; the model updates at the
// rising edge; outputs are sampled 1 ns after it. Registers are read by changing
// addr between clock edges (IRQ-READ, IRQ-LATENCY).
//
// Requirement map:
//   IRQ-RESET D1, D10 | IRQ-REG-RW D2 | IRQ-PARAM D2 and N=8/32/2 instances
//   IRQ-READ every cycle | IRQ-LEVEL D3 | IRQ-EDGE D9 | IRQ-DETECT-DISABLED D3
//   IRQ-W1C D2, D5 | IRQ-ACK D7 | IRQ-SET-WINS D8, D9 | IRQ-MASK D4
//   IRQ-PRIORITY D3, D6 | IRQ-CLAIM D4, D6, D8 | IRQ-LATENCY every cycle
`timescale 1ns / 1ps

module irq_ctrl_tb_core #(
    parameter integer N           = 8,
    parameter integer DIRECTED    = 1,
    parameter integer RAND_CYCLES = 2000
) (
    input  logic   clk,
    output integer passes,
    output integer fails,
    output logic   done
);
    localparam logic [31:0] NMASK = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    logic          rst_n;
    logic [N-1:0]  src;
    logic          we;
    logic [1:0]    addr;
    logic [31:0]   wdata;
    wire  [31:0]   rdata;
    wire           irq;
    wire  [4:0]    irq_id;

    irq_ctrl #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .src   (src),
        .we    (we),
        .addr  (addr),
        .wdata (wdata),
        .rdata (rdata),
        .irq   (irq),
        .irq_id(irq_id)
    );

    // Reference model state from interface_spec.md; bits N and up stay zero.
    logic [31:0] m_en;
    logic [31:0] m_mode;
    logic [31:0] m_pend;
    logic [31:0] m_srcq;

    // Random-phase variables.
    logic [31:0] r_src;
    logic [31:0] r_d;
    logic        r_w;
    logic        r_r;
    logic [1:0]  r_a;
    integer      c;

    function automatic logic [31:0] bitn(input integer i);
        bitn = 32'd1 << i;
    endfunction

    task automatic check(input string tag, input string field,
                         input logic [31:0] got, input logic [31:0] exp);
        if (got === exp) begin
            passes = passes + 1;
        end else begin
            fails = fails + 1;
            $display("FAIL N=%0d t=%0t %s: %s (addr=%0d) got %h expected %h",
                     N, $time, tag, field, addr, got, exp);
        end
    endtask

    // Compare every output and every register against the model.
    task automatic check_all(input string tag);
        logic [31:0] act;
        logic        e_irq;
        logic [4:0]  e_id;
        logic        found;
        integer      k;
        act   = m_en & m_pend;
        e_irq = |act;
        e_id  = 5'd0;
        found = 1'b0;
        for (k = 0; k < 32; k = k + 1)
            if (!found && act[k]) begin
                e_id  = k[4:0];
                found = 1'b1;
            end
        we = 1'b0;
        check(tag, "irq", {31'd0, irq}, {31'd0, e_irq});
        check(tag, "irq_id", {27'd0, irq_id}, {27'd0, e_id});
        addr = 2'd0; #1; check(tag, "ENABLE", rdata, m_en);
        addr = 2'd1; #1; check(tag, "MODE", rdata, m_mode);
        addr = 2'd2; #1; check(tag, "PENDING", rdata, m_pend);
        addr = 2'd3; #1; check(tag, "CLAIM", rdata, {e_irq, 26'd0, e_id});
    endtask

    // One clock cycle: drive at the falling edge, update the model at the rising
    // edge, then compare.
    task automatic step(input logic r, input logic [31:0] s, input logic w,
                        input logic [1:0] a, input logic [31:0] d, input string tag);
        logic [31:0] s32;
        logic [31:0] n_en;
        logic [31:0] n_mode;
        logic [31:0] n_pend;
        logic        det;
        logic        clr;
        integer      k;
        @(negedge clk);
        s32   = s & NMASK;
        rst_n = r;
        src   = s32[N-1:0];
        we    = w;
        addr  = a;
        wdata = d;
        n_pend = 32'd0;
        for (k = 0; k < N; k = k + 1) begin
            // 4.2: level sources detect while high; edge sources detect high-after-low.
            det = s32[k] & (m_mode[k] ? ~m_srcq[k] : 1'b1);
            // 4.3: W1C on PENDING, or an acknowledge naming this source.
            clr = (w && a == 2'd2 && d[k]) || (w && a == 2'd3 && d[4:0] == k[4:0]);
            // 4.3 IRQ-SET-WINS: detection beats a clear at the same edge.
            n_pend[k] = det | (m_pend[k] & ~clr);
        end
        n_en   = (w && a == 2'd0) ? (d & NMASK) : m_en;
        n_mode = (w && a == 2'd1) ? (d & NMASK) : m_mode;
        @(posedge clk);
        if (!r) begin
            m_en   = 32'd0;
            m_mode = 32'd0;
            m_pend = 32'd0;
            m_srcq = 32'd0;
        end else begin
            m_en   = n_en;
            m_mode = n_mode;
            m_pend = n_pend;
            m_srcq = s32;
        end
        #1;
        check_all(tag);
    endtask

    task automatic wr(input logic [1:0] a, input logic [31:0] d, input logic [31:0] s,
                      input string tag);
        step(1'b1, s, 1'b1, a, d, tag);
    endtask

    task automatic idle(input logic [31:0] s, input string tag);
        step(1'b1, s, 1'b0, 2'd0, 32'd0, tag);
    endtask

    // Literal expectations, computed from the specification.
    task automatic expect_rd(input string tag, input logic [1:0] a, input logic [31:0] exp);
        we   = 1'b0;
        addr = a;
        #1;
        check(tag, "rdata literal", rdata, exp);
    endtask

    task automatic expect_irq(input string tag, input logic e_irq, input integer e_id);
        #1;
        check(tag, "irq literal", {31'd0, irq}, {31'd0, e_irq});
        check(tag, "irq_id literal", {27'd0, irq_id}, {27'd0, e_id[4:0]});
    endtask

    initial begin
        passes = 0;
        fails  = 0;
        done   = 1'b0;
        rst_n  = 1'b0;
        src    = '0;
        we     = 1'b0;
        addr   = 2'd0;
        wdata  = 32'd0;
        m_en   = 32'd0;
        m_mode = 32'd0;
        m_pend = 32'd0;
        m_srcq = 32'd0;

        if (DIRECTED != 0 && N >= 8) begin
            // D1 reset: sources high and a write applied while in reset change nothing.
            step(1'b0, NMASK, 1'b1, 2'd0, 32'hFFFF_FFFF, "D1 reset, sources high, write in reset");
            expect_rd("D1", 2'd0, 32'd0);
            expect_rd("D1", 2'd1, 32'd0);
            expect_rd("D1", 2'd2, 32'd0);
            expect_rd("D1", 2'd3, 32'd0);
            expect_irq("D1", 1'b0, 0);
            step(1'b0, 32'd0, 1'b0, 2'd0, 32'd0, "D1 reset");

            // D2 register read/write, unused bits read zero, a PENDING write never sets.
            wr(2'd0, 32'hFFFF_FFFF, 32'd0, "D2 ENABLE all ones");
            expect_rd("D2", 2'd0, NMASK);
            expect_irq("D2 nothing pending", 1'b0, 0);
            wr(2'd1, 32'hA5A5_A5A5, 32'd0, "D2 MODE pattern");
            expect_rd("D2", 2'd1, 32'hA5A5_A5A5 & NMASK);
            expect_rd("D2 ENABLE kept", 2'd0, NMASK);
            wr(2'd0, 32'h5A5A_5A5A, 32'd0, "D2 ENABLE pattern");
            expect_rd("D2", 2'd0, 32'h5A5A_5A5A & NMASK);
            expect_rd("D2 MODE kept", 2'd1, 32'hA5A5_A5A5 & NMASK);
            wr(2'd2, 32'hFFFF_FFFF, 32'd0, "D2 PENDING write never sets");
            expect_rd("D2", 2'd2, 32'd0);
            wr(2'd3, 32'd0, 32'd0, "D2 ack with nothing pending");
            expect_rd("D2", 2'd2, 32'd0);
            wr(2'd1, 32'd0, 32'd0, "D2 MODE clear");
            wr(2'd0, 32'd0, 32'd0, "D2 ENABLE clear");
            expect_rd("D2", 2'd0, 32'd0);
            expect_rd("D2", 2'd1, 32'd0);

            // D3 level detection while disabled; pending is sticky; irq_id 0 while irq low.
            idle(bitn(2), "D3 src2 high one cycle, disabled");
            expect_rd("D3", 2'd2, bitn(2));
            expect_irq("D3 disabled", 1'b0, 0);
            expect_rd("D3 CLAIM", 2'd3, 32'd0);
            idle(32'd0, "D3 src low, pending holds");
            expect_rd("D3", 2'd2, bitn(2));

            // D4 mask and claim.
            wr(2'd0, bitn(2), 32'd0, "D4 enable src2");
            expect_irq("D4", 1'b1, 2);
            expect_rd("D4 CLAIM", 2'd3, 32'h8000_0002);
            wr(2'd0, bitn(3), 32'd0, "D4 enable only src3, not pending");
            expect_irq("D4 masked", 1'b0, 0);
            expect_rd("D4 CLAIM", 2'd3, 32'd0);

            // D5 two detections at one edge; partial W1C.
            idle(bitn(1) | bitn(3), "D5 src1 and src3 at one edge");
            expect_rd("D5", 2'd2, bitn(1) | bitn(2) | bitn(3));
            expect_irq("D5", 1'b1, 3);
            wr(2'd2, bitn(2) | bitn(0), 32'd0, "D5 W1C src2 and non-pending src0");
            expect_rd("D5", 2'd2, bitn(1) | bitn(3));
            wr(2'd2, 32'd0, 32'd0, "D5 W1C zeros");
            expect_rd("D5", 2'd2, bitn(1) | bitn(3));

            // D6 priority with several requesters.
            idle(bitn(N - 1), "D6 src N-1");
            expect_rd("D6", 2'd2, bitn(1) | bitn(3) | bitn(N - 1));
            wr(2'd0, NMASK, 32'd0, "D6 enable all");
            expect_irq("D6 all", 1'b1, 1);
            expect_rd("D6 CLAIM", 2'd3, 32'h8000_0001);
            wr(2'd0, bitn(3) | bitn(N - 1), 32'd0, "D6 enable 3 and N-1");
            expect_irq("D6 3 and N-1", 1'b1, 3);
            wr(2'd0, bitn(N - 1), 32'd0, "D6 enable N-1");
            expect_irq("D6 N-1", 1'b1, N - 1);
            expect_rd("D6 CLAIM", 2'd3, 32'h8000_0000 | (N - 1));
            wr(2'd0, NMASK, 32'd0, "D6 enable all again");

            // D7 acknowledge.
            wr(2'd3, 32'd1, 32'd0, "D7 ack 1");
            expect_rd("D7", 2'd2, bitn(3) | bitn(N - 1));
            expect_irq("D7", 1'b1, 3);
            wr(2'd3, N, 32'd0, "D7 ack number N");
            expect_rd("D7", 2'd2, bitn(3) | bitn(N - 1));
            if (N < 32) begin
                wr(2'd3, 32'd31, 32'd0, "D7 ack 31, out of range");
                expect_rd("D7", 2'd2, bitn(3) | bitn(N - 1));
            end
            wr(2'd3, 32'hFFFF_FFE3, 32'd0, "D7 ack 3 with high wdata bits set");
            expect_rd("D7", 2'd2, bitn(N - 1));
            expect_irq("D7", 1'b1, N - 1);
            wr(2'd3, N - 1, 32'd0, "D7 ack N-1");
            expect_rd("D7", 2'd2, 32'd0);
            expect_irq("D7 empty", 1'b0, 0);
            expect_rd("D7 CLAIM", 2'd3, 32'd0);

            // D8 set wins over clear for a level source.
            idle(bitn(0), "D8 src0 high");
            expect_irq("D8", 1'b1, 0);
            expect_rd("D8 CLAIM", 2'd3, 32'h8000_0000);
            wr(2'd2, bitn(0), bitn(0), "D8 W1C src0 while high");
            expect_rd("D8", 2'd2, bitn(0));
            wr(2'd3, 32'd0, bitn(0), "D8 ack src0 while high");
            expect_rd("D8", 2'd2, bitn(0));
            wr(2'd3, 32'd0, 32'd0, "D8 ack src0 after it falls");
            expect_rd("D8", 2'd2, 32'd0);
            expect_irq("D8", 1'b0, 0);

            // D9 rising-edge mode.
            wr(2'd1, bitn(3), 32'd0, "D9 src3 edge mode");
            expect_rd("D9", 2'd1, bitn(3));
            idle(bitn(3), "D9 src3 rises");
            expect_rd("D9", 2'd2, bitn(3));
            expect_irq("D9", 1'b1, 3);
            wr(2'd2, bitn(3), bitn(3), "D9 W1C while held high");
            expect_rd("D9", 2'd2, 32'd0);
            idle(bitn(3), "D9 held high, no new edge");
            expect_rd("D9", 2'd2, 32'd0);
            expect_irq("D9", 1'b0, 0);
            idle(32'd0, "D9 falls");
            expect_rd("D9", 2'd2, 32'd0);
            wr(2'd2, bitn(3), bitn(3), "D9 rise at the edge of a W1C, set wins");
            expect_rd("D9", 2'd2, bitn(3));
            wr(2'd3, 32'd3, bitn(3), "D9 ack while held");
            expect_rd("D9", 2'd2, 32'd0);
            idle(bitn(2) | bitn(3), "D9 src2 rises in level mode, src3 held");
            expect_rd("D9", 2'd2, bitn(2));
            wr(2'd1, bitn(2) | bitn(3), bitn(2) | bitn(3), "D9 src2 to edge mode while held");
            expect_rd("D9", 2'd2, bitn(2));
            expect_rd("D9", 2'd1, bitn(2) | bitn(3));
            wr(2'd2, bitn(2), bitn(2) | bitn(3), "D9 W1C src2, edge mode, held");
            expect_rd("D9", 2'd2, 32'd0);
            idle(32'd0, "D9 sources low");
            wr(2'd1, 32'd0, 32'd0, "D9 MODE back to level");
            expect_rd("D9", 2'd1, 32'd0);

            // D10 reset in the middle of operation.
            idle(bitn(1) | bitn(N - 1), "D10 src1 and N-1");
            expect_irq("D10", 1'b1, 1);
            wr(2'd1, bitn(N - 1), bitn(N - 1), "D10 N-1 to edge mode, held");
            step(1'b0, bitn(N - 1), 1'b0, 2'd0, 32'd0, "D10 reset mid-operation");
            expect_rd("D10", 2'd0, 32'd0);
            expect_rd("D10", 2'd1, 32'd0);
            expect_rd("D10", 2'd2, 32'd0);
            expect_rd("D10", 2'd3, 32'd0);
            expect_irq("D10", 1'b0, 0);
            idle(bitn(N - 1), "D10 release, N-1 still high, level mode");
            expect_rd("D10", 2'd2, bitn(N - 1));
            expect_irq("D10 disabled", 1'b0, 0);
            wr(2'd2, NMASK, 32'd0, "D10 clear all");
            expect_rd("D10", 2'd2, 32'd0);
        end else begin
            step(1'b0, 32'd0, 1'b0, 2'd0, 32'd0, "reset");
            step(1'b0, NMASK, 1'b1, 2'd0, 32'hFFFF_FFFF, "reset with write");
        end

        // Constrained-random traffic, checked against the model every cycle.
        r_src = 32'd0;
        for (c = 0; c < RAND_CYCLES; c = c + 1) begin
            r_src = r_src ^ ($urandom & $urandom);
            r_r   = ($urandom_range(0, 99) != 0);
            r_w   = ($urandom_range(0, 1) != 0);
            r_a   = $urandom_range(0, 3);
            r_d   = $urandom;
            if (r_a == 2'd3 && $urandom_range(0, 3) != 0)
                r_d[4:0] = $urandom_range(0, N - 1);
            if (r_a == 2'd2 && $urandom_range(0, 1) != 0)
                r_d = r_d & $urandom;
            step(r_r, r_src, r_w, r_a, r_d, "R random");
        end

        done = 1'b1;
    end
endmodule

module irq_ctrl_tb;
    logic   clk;
    integer p8, f8, p32, f32, p2, f2;
    logic   d8, d32, d2;
    string  nonce;
    logic   have_nonce;
    logic   verdict_done;

    initial clk = 1'b0;
    always #50 clk = ~clk;

    irq_ctrl_tb_core #(.N(8),  .DIRECTED(1), .RAND_CYCLES(3000)) u_n8  (.clk(clk), .passes(p8),  .fails(f8),  .done(d8));
    irq_ctrl_tb_core #(.N(32), .DIRECTED(1), .RAND_CYCLES(3000)) u_n32 (.clk(clk), .passes(p32), .fails(f32), .done(d32));
    irq_ctrl_tb_core #(.N(2),  .DIRECTED(0), .RAND_CYCLES(2000)) u_n2  (.clk(clk), .passes(p2),  .fails(f2),  .done(d2));

    task automatic verdict(input integer extra_fail);
        integer p;
        integer f;
        p = p8 + p32 + p2;
        f = f8 + f32 + f2 + extra_fail;
        if (!have_nonce) f = f + 1;
        $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce, p, f);
    endtask

    initial begin
        verdict_done = 1'b0;
        have_nonce   = 1'b1;
        if ($value$plusargs("nonce=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_NONCE=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("sim_nonce=%s", nonce)) have_nonce = 1'b1;
        else begin
            have_nonce = 1'b0;
            nonce = "none";
            $display("FAIL no nonce plusarg found");
        end
        wait (d8 === 1'b1 && d32 === 1'b1 && d2 === 1'b1);
        #1;
        if (!verdict_done) begin
            verdict_done = 1'b1;
            verdict(0);
            $finish;
        end
    end

    initial begin
        #20000000;
        if (!verdict_done) begin
            verdict_done = 1'b1;
            $display("FAIL watchdog: test did not complete");
            verdict(1);
            $finish;
        end
    end
endmodule
=== END FILE ===
